{"cards": [{"node_code": "N_4f071da7f9db6a36", "definition": "研究工业机器人的本体构型分类、负载能力参数、运动范围及末端执行器（夹具、焊枪等）的选型、设计与集成技术。", "boundary": "聚焦于机器人硬件本体及其末端附件的工程选型与匹配。边界在于强调“硬件配置”与“物理接口”，不涉及具体的工艺过程控制逻辑或系统级调度。若涉及末端执行器的复杂传感与控制算法，需区分于“机器感知”或“控制理论”。", "includes": ["六轴、SCARA、Delta等工业机器人构型特点及选型依据", "机器人负载、臂展、重复精度等关键参数定义与匹配", "末端执行器（夹爪、吸盘、焊枪、喷枪）的结构设计与接口标准"], "excludes": ["机器人本体的运动学解算或动力学建模理论", "末端执行器内部的复杂传感器信号处理或智能控制算法"], "sibling_distinctions": [{"other_code": "N_5a6c8e86e80b9176", "rule": "本节点关注机器人本体及末端附件的通用硬件选型与参数，兄弟节点关注搬运、码垛等特定任务下的系统布局与工艺实现。"}, {"other_code": "N_2d1560e50d710d17", "rule": "本节点关注焊接、喷涂等工艺所需的末端工具硬件本身，兄弟节点关注焊接、喷涂工艺过程中的机器人轨迹与参数控制。"}], "cross_boundary_rule": "若末端附件涉及复杂的力控或视觉伺服，硬件结构主挂载本节点，控制策略可次关联“机器感知、智能控制与自主系统”。"}, {"node_code": "N_fcbc187db74d54ff", "definition": "研究工业机器人的示教再现方法、顺序控制逻辑、离线/在线编程技术及其在应用系统中的工程实现。", "boundary": "聚焦于面向工程应用的机器人编程与控制指令生成。边界在于强调“操作层面”的编程与逻辑控制，不涉及底层运动控制算法推导或通用任务规划理论。若涉及基于AI的自主路径规划，需区分于“机器感知、智能控制与自主系统”。", "includes": ["示教器操作、点位示教、轨迹示教等再现技术", "机器人编程语言（如RAPID, KRL）及顺序控制逻辑", "离线编程软件、路径仿真及与PLC/上位机的通信接口"], "excludes": ["通用的运动学逆解算法或动力学控制理论", "基于深度学习的自主导航或复杂环境下的实时避障算法"], "sibling_distinctions": [{"other_code": "N_7df5185c3d50487f", "rule": "本节点关注工程层面的编程指令与顺序控制，兄弟节点关注通用的轨迹生成、避障算法及任务规划理论。"}, {"other_code": "N_4f071da7f9db6a36", "rule": "本节点关注机器人的软件控制与编程逻辑，兄弟节点关注机器人本体硬件及末端附件的物理选型。"}], "cross_boundary_rule": "若编程涉及复杂的实时力控或视觉反馈闭环，编程接口主挂载本节点，底层控制算法可次关联“控制理论与控制工程”。"}]}
